import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = data[2:2 + r]
total = 0
for a in range(r):
    for b in range(a + 1, r):
        if any('1' in g[m] for m in range(a + 1, b)):
            continue
        for i in range(c):
            if g[a][i] == '1':
                for j in range(c):
                    if g[b][j] == '1':
                        total += 1
print(total)

